public final class ArenaCommand implements CommandExecutor, TabCompleter {
    private final Plugin plugin; private final ArenaService arena; private final ChampionshipManager championships;
    private final MatchManager matches; private final PlayerSessionManager sessions; private final FileConfiguration minigames; private final int rankingLimit;
    public ArenaCommand(Plugin plugin,ArenaService arena,ChampionshipManager championships,MatchManager matches,PlayerSessionManager sessions,FileConfiguration minigames,int rankingLimit){this.plugin=plugin;this.arena=arena;this.championships=championships;this.matches=matches;this.sessions=sessions;this.minigames=minigames;this.rankingLimit=rankingLimit;}

    @Override public boolean onCommand(CommandSender s,Command command,String label,String[] a){if(a.length==0||a[0].equalsIgnoreCase("help")){help(s);return true;}try{switch(a[0].toLowerCase(Locale.ROOT)){
        case "create"->{admin(s);require(a,3,"/arena create <id> <nome>");async(s,arena.createChampionship(a[1],join(a,2)),c->ok(s,"Campeonato criado: "+c.id()));}
        case "prepare"->legacyTransition(s,a,ChampionshipState.PREPARING); case "start"->legacyTransition(s,a,ChampionshipState.RUNNING); case "pause"->legacyTransition(s,a,ChampionshipState.PAUSED); case "resume"->legacyTransition(s,a,ChampionshipState.RUNNING); case "cancel"->legacyTransition(s,a,ChampionshipState.CANCELLED);
        case "finish"->{admin(s);require(a,2,"/arena finish <id>");async(s,championships.finish(a[1],actor(s)),winner->ok(s,"Campeonato finalizado. Campeao: "+winner));}
        case "list"->async(s,arena.championships(),list->{if(list.isEmpty())info(s,"Nenhum campeonato.");else list.forEach(c->info(s,c.id()+" - "+c.name()+" ["+c.state()+"]"));});
        case "join"->{player(s);require(a,2,"/arena join <campeonato> [equipe]");Player p=(Player)s;async(s,arena.registerPlayer(a[1],p.getUniqueId(),p.getName(),a.length>2?a[2]:null),v->ok(s,"Inscricao registrada."));}
        case "register"->register(s,a); case "next"->next(s,a); case "status"->status(s,a); case "score"->score(s,a); case "ranking"->ranking(s,a); case "champ"->champ(s,a); case "team"->team(s,a); case "match"->match(s,a); default->help(s);
    }}catch(IllegalArgumentException|IllegalStateException e){error(s,e.getMessage());}return true;}

    private void register(CommandSender s,String[]a){admin(s);require(a,3,"/arena register <campeonato> <nickname> OU <campeonato> <uuid> <nome> [equipe]");try{UUID id=UUID.fromString(a[2]);require(a,4,"/arena register <campeonato> <uuid> <nome> [equipe]");async(s,arena.registerPlayer(a[1],id,a[3],a.length>4?a[4]:null),v->ok(s,"Participante inscrito."));return;}catch(IllegalArgumentException ignored){}Player online=Bukkit.getPlayerExact(a[2]);if(online!=null){async(s,arena.registerPlayer(a[1],online.getUniqueId(),online.getName(),null),v->ok(s,"Participante inscrito: "+online.getName()));return;}PlayerProfile profile=Bukkit.createPlayerProfile(a[2]);profile.update().thenCompose(updated->{if(updated.getUniqueId()==null)throw new CompletionException(new IllegalArgumentException("Nickname nao encontrado: "+a[2]));return arena.registerPlayer(a[1],updated.getUniqueId(),updated.getName()==null?a[2]:updated.getName(),null);}).whenComplete((v,e)->main(()->{if(e!=null)error(s,root(e).getMessage());else ok(s,"Participante inscrito: "+a[2]);}));}
    private CompletableFuture<UUID> resolveParticipant(String championship,String value){try{return CompletableFuture.completedFuture(UUID.fromString(value));}catch(IllegalArgumentException ignored){return matches.participants(championship).thenApply(list->list.stream().filter(p->p.playerName().equalsIgnoreCase(value)).map(ParticipantInfo::playerId).findFirst().orElseThrow(()->new IllegalArgumentException("Participante nao inscrito: "+value)));}}

    private void champ(CommandSender s,String[]a){admin(s);require(a,2,"/arena champ <create|details>");switch(a[1].toLowerCase(Locale.ROOT)){case "create"->{require(a,6,"/arena champ create <id> <individual|teams> <gamesCSV> <nome>");ChampionshipMode mode=ChampionshipMode.valueOf(a[3].toUpperCase(Locale.ROOT));async(s,championships.create(a[2],join(a,5),mode,List.of(a[4].split(",")),TieBreaker.MOST_WINS,actor(s)),d->ok(s,"Campeonato completo criado: "+d.id()));}case "details"->{require(a,3,"/arena champ details <id>");async(s,championships.details(a[2]),d->info(s,d.id()+" modo="+d.mode()+" rodada="+d.currentRound()+" jogos="+String.join(",",d.minigames())+" campeao="+d.championId()));}default->throw new IllegalArgumentException("Subcomando champ invalido");}}
    private void team(CommandSender s,String[]a){admin(s);require(a,2,"/arena team <create|assign|ranking>");switch(a[1].toLowerCase(Locale.ROOT)){case "create"->{require(a,5,"/arena team create <campeonato> <id> <nome>");async(s,championships.createTeam(a[2],a[3],join(a,4),actor(s)),t->ok(s,"Equipe criada: "+t.id()));}case "assign"->{require(a,5,"/arena team assign <campeonato> <nickname-ou-uuid> <equipe>");resolveParticipant(a[2],a[3]).thenCompose(id->championships.assignTeam(a[2],id,a[4],actor(s))).whenComplete((v,e)->main(()->{if(e!=null)error(s,root(e).getMessage());else ok(s,"Participante atribuido.");}));}case "ranking"->{require(a,3,"/arena team ranking <campeonato>");async(s,championships.teamRanking(a[2],rankingLimit),rows->{for(int i=0;i<rows.size();i++){var r=rows.get(i);info(s,(i+1)+". "+r.teamName()+" - "+r.points()+" pts, "+r.wins()+" vitorias");}});}default->throw new IllegalArgumentException("Subcomando team invalido");}}

    private void next(CommandSender s,String[]a){
        admin(s);require(a,2,"/arena next <campeonato>");String id=a[1];
        championships.details(id).thenCompose(d->{
            if(d.state()!=ChampionshipState.WAITING&&d.state()!=ChampionshipState.RUNNING)return CompletableFuture.failedFuture(new IllegalStateException("Campeonato deve estar em WAITING ou RUNNING"));
            int round=d.currentRound()+1;String game=d.minigames().get((round-1)%d.minigames().size());var adapter=matches.minigame(game).orElseThrow(()->new IllegalStateException("Minigame nao implementado ou indisponivel: "+game));
            String configured=minigames.getString("minigames."+game+".arena");if(configured==null||configured.isBlank())return CompletableFuture.failedFuture(new IllegalStateException("Arena nao configurada em minigames.yml para "+game));
            if(!adapter.supportsArena(configured))return CompletableFuture.failedFuture(new IllegalStateException("Arena inexistente ou incompleta no minigame "+game+": "+configured));
            return matches.calendar(id).thenCombine(matches.participants(id),(calendar,players)->new NextData(d,round,game,configured,calendar,players));
        }).thenCompose(data->{
            if(data.players().isEmpty())return CompletableFuture.failedFuture(new IllegalStateException("Campeonato sem participantes"));
            if(data.calendar().stream().anyMatch(m->m.round()==data.round()))return CompletableFuture.failedFuture(new IllegalStateException("A rodada "+data.round()+" ja possui partida; use restart para reinicia-la"));
            CompletableFuture<?> state=data.details().state()==ChampionshipState.WAITING?championships.transition(id,ChampionshipState.PREPARING,actor(s)).thenCompose(x->championships.transition(id,ChampionshipState.RUNNING,actor(s))):CompletableFuture.completedFuture(data.details());
            return state.thenCompose(x->{String matchId=data.details().id()+"-r"+data.round();return matches.create(matchId,data.details().id(),data.round(),data.game(),data.arena(),data.players().stream().map(ParticipantInfo::playerId).toList(),true,Instant.now(),actor(s)).thenCompose(m->matches.transition(m.id(),MatchState.PREPARING,actor(s),null));});
        }).whenComplete((m,e)->main(()->{if(e!=null)error(s,root(e).getMessage());else ok(s,"Rodada preparada: "+m.id()+". O minigame controlara a contagem e o inicio.");}));
    }
    private record NextData(ChampionshipDetails details,int round,String game,String arena,List<ArenaMatch>calendar,List<ParticipantInfo>players){}
    private void status(CommandSender s,String[]a){require(a,2,"/arena status <campeonato>");String id=a[1];championships.details(id).thenCombine(matches.participants(id),StatusData::new).thenCombine(matches.calendar(id),(d,c)->new StatusData(d.details(),d.players(),c,List.of())).thenCombine(arena.ranking(id,rankingLimit),(d,r)->new StatusData(d.details(),d.players(),d.calendar(),r)).whenComplete((d,e)->main(()->{if(e!=null){error(s,root(e).getMessage());return;}int next=d.details().currentRound()+1;String game=d.details().minigames().isEmpty()?"-":d.details().minigames().get((next-1)%d.details().minigames().size());info(s,d.details().name()+" ["+d.details().state()+"] rodada="+d.details().currentRound()+" proximo="+game);info(s,"Jogadores="+d.players().size()+" equipes="+d.players().stream().map(ParticipantInfo::teamId).filter(Objects::nonNull).distinct().count());d.calendar().stream().filter(m->m.state()!=MatchState.FINISHED&&m.state()!=MatchState.CANCELLED).findFirst().ifPresent(m->info(s,"Partida ativa: "+m.id()+" ["+m.state()+"] arena="+m.arena()));for(int i=0;i<d.ranking().size();i++)info(s,(i+1)+". "+d.ranking().get(i).playerName()+" - "+d.ranking().get(i).points()+" pts");}));}
    private record StatusData(ChampionshipDetails details,List<ParticipantInfo>players,List<ArenaMatch>calendar,List<RankingEntry>ranking){StatusData(ChampionshipDetails d,List<ParticipantInfo>p){this(d,p,List.of(),List.of());}}

    private void match(CommandSender s,String[]a){admin(s);require(a,2,"/arena match <create|prepare|countdown|start|finish|cancel|status|list|restart|abandon>");switch(a[1].toLowerCase(Locale.ROOT)){case "create"->{require(a,8,"/arena match create <id> <camp> <round> <game> <arena> <uuidCSV>");async(s,matches.create(a[2],a[3],Integer.parseInt(a[4]),a[5],a[6],Arrays.stream(a[7].split(",")).map(UUID::fromString).toList(),true,Instant.now(),actor(s)),m->ok(s,"Partida criada: "+m.id()));}case "prepare"->matchTransition(s,a,MatchState.PREPARING,null);case "countdown"->matchTransition(s,a,MatchState.COUNTDOWN,null);case "start"->{require(a,3,"/arena match start <id>");async(s,matches.match(a[2]),m->{m.participants().forEach(id->{Player p=Bukkit.getPlayer(id);if(p!=null)sessions.capture(p);});async(s,matches.transition(a[2],MatchState.RUNNING,actor(s),null),started->ok(s,"Partida iniciada: "+started.id()));});}case "cancel"->{require(a,3,"/arena match cancel <id> [motivo]");matchTransition(s,a,MatchState.CANCELLED,a.length>3?join(a,3):"cancelamento administrativo");restoreAfter(a[2]);}case "finish"->finishMatch(s,a);case "status"->{require(a,3,"/arena match status <id>");async(s,matches.match(a[2]),m->info(s,m.id()+" ["+m.state()+"] jogo="+m.minigame()+" arena="+m.arena()+" jogadores="+m.participants().size()+" duracao="+m.duration()));}case "list"->{require(a,3,"/arena match list <campeonato>");async(s,matches.calendar(a[2]),list->list.forEach(m->info(s,"#"+m.round()+" "+m.id()+" "+m.minigame()+" ["+m.state()+"]")));}case "restart"->{require(a,4,"/arena match restart <antiga> <nova>");async(s,matches.restartRound(a[2],a[3],actor(s)),m->ok(s,"Rodada reiniciada sem reaplicar resultado: "+m.id()));}case "abandon"->{require(a,4,"/arena match abandon <id> <uuid>");async(s,matches.abandon(a[2],UUID.fromString(a[3]),actor(s)),v->ok(s,"Abandono registrado."));}default->throw new IllegalArgumentException("Subcomando match invalido");}}
    private void finishMatch(CommandSender s,String[]a){require(a,5,"/arena match finish <id> <result-id> <uuid:points[:team],...>");List<ResultEntry>entries=new ArrayList<>();int pos=1;for(String token:a[4].split(",")){String[]p=token.split(":");entries.add(new ResultEntry(UUID.fromString(p[0]),p.length>2?p[2]:null,pos,Integer.parseInt(p[1]),pos==1));pos++;}boolean tie=entries.size()>1&&entries.get(0).points()==entries.get(1).points();async(s,matches.finish(a[2],new MatchResult(a[3],a[2],entries,tie,Instant.now()),actor(s)),inserted->{if(inserted){ok(s,"Resultado oficial registrado.");restoreAfter(a[2]);}else error(s,"Resultado duplicado ou partida nao executando.");});}
    private void restoreAfter(String id){matches.match(id).thenAccept(m->main(()->m.participants().forEach(uuid->{Player p=Bukkit.getPlayer(uuid);if(p!=null)sessions.restore(p,true);})));}
    private void matchTransition(CommandSender s,String[]a,MatchState next,String reason){require(a,3,"/arena match "+a[1]+" <id>");async(s,matches.transition(a[2],next,actor(s),reason),m->ok(s,"Partida agora esta "+m.state()));}
    private void ranking(CommandSender s,String[]a){require(a,2,"/arena ranking <campeonato>");async(s,arena.ranking(a[1],rankingLimit),rows->{info(s,"Ranking - "+a[1]);for(int i=0;i<rows.size();i++)info(s,(i+1)+". "+rows.get(i).playerName()+" - "+rows.get(i).points()+" pts");});}
    private void score(CommandSender s,String[]a){admin(s);require(a,6,"/arena score <camp> <jogador> <pontos> <origem> <event-id>");UUID id;try{id=UUID.fromString(a[2]);}catch(IllegalArgumentException e){Player p=Bukkit.getPlayerExact(a[2]);if(p==null)throw new IllegalArgumentException("Jogador offline: use UUID");id=p.getUniqueId();}async(s,championships.administrativeScore(a[1],id,Integer.parseInt(a[3]),a[4],a[5],actor(s)),inserted->{if(inserted)ok(s,"Pontuacao registrada e auditada.");else error(s,"Evento duplicado.");});}
    private void legacyTransition(CommandSender s,String[]a,ChampionshipState state){admin(s);require(a,2,"/arena "+a[0]+" <id>");async(s,championships.transition(a[1],state,actor(s)),c->ok(s,"Estado atualizado: "+c.state()));}
    private <T>void async(CommandSender s,CompletableFuture<T>f,Consumer<T>success){f.whenComplete((v,e)->main(()->{if(e!=null)error(s,root(e).getMessage());else success.accept(v);}));}
    private void main(Runnable r){Bukkit.getScheduler().runTask(plugin,r);} private Throwable root(Throwable t){while((t instanceof CompletionException||t instanceof ExecutionException)&&t.getCause()!=null)t=t.getCause();return t;}
    private String actor(CommandSender s){return s.getName();} private String join(String[]a,int from){return String.join(" ",Arrays.copyOfRange(a,from,a.length));} private void admin(CommandSender s){if(!s.hasPermission("arena.admin"))throw new IllegalStateException("Sem permissao: arena.admin");} private void player(CommandSender s){if(!(s instanceof Player)||!s.hasPermission("arena.play"))throw new IllegalStateException("Comando exclusivo para jogadores autorizados");} private void require(String[]a,int n,String usage){if(a.length<n)throw new IllegalArgumentException("Uso: "+usage);} private void help(CommandSender s){info(s,"/arena champ|team|match|register|next|status|ranking - consulte o README");} private void ok(CommandSender s,String m){s.sendMessage(Component.text(m,NamedTextColor.GREEN));} private void info(CommandSender s,String m){s.sendMessage(Component.text(m,NamedTextColor.GOLD));} private void error(CommandSender s,String m){s.sendMessage(Component.text(m==null?"Erro interno":m,NamedTextColor.RED));}
    @Override public List<String>onTabComplete(CommandSender s,Command c,String alias,String[]a){if(a.length==1)return List.of("help","list","join","ranking","champ","team","match","register","next","status","create","prepare","start","pause","resume","finish","cancel","score").stream().filter(x->x.startsWith(a[0].toLowerCase())).toList();if(a.length==2&&a[0].equalsIgnoreCase("match"))return List.of("create","prepare","countdown","start","finish","cancel","status","list","restart","abandon");if(a.length==2&&a[0].equalsIgnoreCase("team"))return List.of("create","assign","ranking");return List.of();}
}
